#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    cin >> n >> k;

    map<long long, long long> freq;
    freq[0] = 1;

    long long cur = 0;
    long long answer = 0;

    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;

        cur += x;

        answer += freq[cur - k];
        ++freq[cur];
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> diff(n + 1, 0);

    while (q--) {
        int l, r;
        long long x;
        cin >> l >> r >> x;

        --l;
        --r;

        diff[l] += x;
        diff[r + 1] -= x;
    }

    long long cur = 0;

    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        cout << cur << (i + 1 == n ? '\n' : ' ');
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;

    vector<vector<long long>> prefix(n + 1, vector<long long>(m + 1, 0));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            long long x;
            cin >> x;

            prefix[i][j] = x
                + prefix[i - 1][j]
                + prefix[i][j - 1]
                - prefix[i - 1][j - 1];
        }
    }

    while (q--) {
        int r1, c1, r2, c2;
        cin >> r1 >> c1 >> r2 >> c2;

        long long answer = prefix[r2][c2]
            - prefix[r1 - 1][c2]
            - prefix[r2][c1 - 1]
            + prefix[r1 - 1][c1 - 1];

        cout << answer << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;

    vector<vector<long long>> diff(n + 2, vector<long long>(m + 2, 0));

    while (q--) {
        int r1, c1, r2, c2;
        long long x;
        cin >> r1 >> c1 >> r2 >> c2 >> x;

        diff[r1][c1] += x;
        diff[r2 + 1][c1] -= x;
        diff[r1][c2 + 1] -= x;
        diff[r2 + 1][c2 + 1] += x;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            diff[i][j] += diff[i - 1][j]
                + diff[i][j - 1]
                - diff[i - 1][j - 1];

            cout << diff[i][j] << (j == m ? '\n' : ' ');
        }
    }

    return 0;
}
